<?php use VazinCMS\Security;require __DIR__.'/partials/head.php';?><section class="admin-title"><div><span class="eyebrow">تاریخچه محتوا</span><h1>نسخه‌های قبلی</h1><p>هر بار ویرایش، نسخه قبلی خودکار نگهداری می‌شود.</p></div><span class="metric"><b><?=count($revisions)?></b> نسخه اخیر</span></section><?php if(isset($_GET['restored'])):?><div class="notice success">نسخه انتخابی بازیابی شد و نسخه فعلی نیز محفوظ ماند.</div><?php endif;?><section class="revision-list"><?php foreach($revisions as $revision):?><article class="revision-card"><div><strong><?=Security::e($revision['page_title'])?></strong><span><?=Security::e($revision['locale'])?> · <?=Security::e($revision['created_at'])?></span><p><?=Security::e(mb_substr(strip_tags($revision['body']),0,150))?></p></div><form method="post" data-confirm="این نسخه بازیابی شود؟"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="revision_id" value="<?=(int)$revision['id']?>"><button class="secondary">بازیابی</button></form></article><?php endforeach;?><?php if(!$revisions):?><div class="empty-state"><b>هنوز نسخه‌ای ثبت نشده</b><p>پس از اولین ویرایش صفحه، تاریخچه اینجا ظاهر می‌شود.</p></div><?php endif;?></section><?php require __DIR__.'/partials/foot.php';?>
